def total(numbers):
    return sum(numbers)


def mean(numbers):
    return total(numbers) / len(numbers)


def median(numbers):
    ordered = sorted(numbers)
    n = len(ordered)
    mid = n // 2
    if n % 2 == 1:
        return ordered[mid]
    return (ordered[mid - 1] + ordered[mid]) / 2
